using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.ToList())if(w is Dialog_MiniGame||w is Dialog_Difficulty||w is FloatMenu)w.Close();TogetherMatch.Reset();var map=Find.CurrentMap;var p=((Pawn[])Host.State["pair"])[0];var defs=new[]{"Joy_PunchingBag","Joy_DartsBoard","Joy_Arcade"};var boards=new Thing[3];for(int i=0;i<3;i++){var def=DefDatabase<ThingDef>.GetNamed(defs[i]);var b=ThingMaker.MakeThing(def,def.MadeFromStuff?GenStuff.DefaultStuffFor(def):null);b.SetFaction(Faction.OfPlayer);GenSpawn.Spawn(b,new IntVec3(125+10*i,0,70),map);boards[i]=b;}Host.State["extensionBoards"]=boards;PRMod.Settings.playTogether=true;PRMod.Settings.linkToPawnSkill=false;string log=Host.Root+"/menu-gate-clear-r2.txt";File.WriteAllText(log,"Actual furniture action, together ON, skill linkage OFF.\n");int index=0,stage=0,start=0;bool anyOpponentMenu=false;Action begin=()=>{p.drafter.Drafted=false;p.jobs.EndCurrentJob(JobCondition.InterruptForced);p.Position=GenRadial.RadialCellsAround(boards[index].Position,6,true).First(c=>c.InBounds(map)&&c.Standable(map)&&!c.AdjacentTo8WayOrInside(boards[index]));p.Notify_Teleported();p.needs.food.CurLevelPercentage=1;p.needs.rest.CurLevelPercentage=1;boards[index].TryGetComp<CompMiniGame>().CompFloatMenuOptions(p).First().action();start=Find.TickManager.TicksGame;};begin();Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;File.AppendAllText(log,e+" job="+p.CurJob+" pos="+p.Position+"\\n");anyOpponentMenu|=Find.WindowStack.Windows.Any(w=>w is FloatMenu);var d=Find.WindowStack.Windows.OfType<Dialog_Difficulty>().FirstOrDefault();var mini=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(d!=null||mini!=null||e>1000){File.AppendAllText(log,defs[index]+" difficulty="+(d!=null)+" mini="+(mini!=null)+" opponentMenuSeen="+anyOpponentMenu+" ticks="+e+"\n");d?.Close();mini?.Close();index++;if(index==3){foreach(var name in new[]{"PR_Chess","PR_Poker","PR_Horseshoes","PR_Hoopstone","PR_Ur","PR_Billiards"}){var game=DefDatabase<MiniGameDef>.GetNamed(name);var b=map.listerThings.AllThings.First(t=>t.TryGetComp<CompMiniGame>()?.Game==game);GameEntry.StartNew(game,b,p);var menu=Find.WindowStack.Windows.OfType<FloatMenu>().FirstOrDefault();File.AppendAllText(log,name+" opponentMenu="+(menu!=null)+"\n");menu?.Close();}Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}else{anyOpponentMenu=false;begin();}}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Testing 1-seat menu gates and retained multi-seat opponent menus.";}}


